import React from "react";
// import "./ContactInfo"
// import { Link } from "react-router-dom";
import styled from "styled-components";

import { Tablet } from "../Responsive";
const Wrapper = styled.div`
.head {
    height: 20vh;
    background-image: url("/images/hero.jpeg");
    background-position: center;
    background-size: cover;
    position: relative;
    /* z-index: -2; */
    display: flex;
    justify-content: center;
    align-items: center;
    color: white;
    padding: 20px;
    margin-bottom: 20px;
}

.head .head-bg {
    position: absolute;
    width: 100%;
    height: 100%;
    background-color: rgba(0, 0, 0, 0.8);
    z-index: 1;
}

.head h1 {
    z-index: 2;
    text-align: center;
}

.contact .info{
    display: grid;
    justify-content: center;
    grid-template-columns: 90%;
}
.contact .title{
    display: flex;
    flex-direction: column;
    align-items: center;
}
.contact .info div{
    display: flex,
    flex-direction: column;
    align-items: center;
    border-left: 2px solid rgba(0, 0, 0, 0.2);
    padding-left: 20px;
}
.contact .info div h5{
    color: var(--primary-color);
    margin-bottom: 15px;
}
.contact .info div p{

}
.contact .info div p span{
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 5px;
    border-radius: 50%;
    width: 40px;
    height: 40px;
    background: black;
    color: var(--primary-color);
}
.contact .info div p.icon{
    display: flex;
    justify-content: start;
    align-items: center;
    align-self: end;
}
.contact .info .info-one{

}
.contact .form{
    background: black;
    padding: 40px;
    margin: 30px 5px;
    border-radius: 10px;
    color: white;
}
.contact .form input,.contact .form textarea, .contact .form button {
    border-radius: 20px 0 20px 20px;
}


`;
function ContactInfo() {
  return (
    <Wrapper>
      <div class="contact">
        <div class="head">
          <div class='head-bg'></div>
          <h1 class="text-bold">Contact Us</h1>
        </div>
        <div class="content container">
          <div class="title my-5">
            <h2 class="text-bold">Get In Touch</h2>
            <p>let's Organise Something Awesome Together</p>
          </div>
          <div class="info my-3">
            <div class="info-one">
              <h5>General Information</h5>
              <p>For general information or information about Ahom Hotel story and services, contact:</p>
              <p class="icon"><span class="me-2">
                <i class="fa-solid fa-envelope-circle-check address-icon"></i></span>info@ahomhotel.com
              </p>
            </div>
            <div class="info-two">
              <h5>Bookings/Reservations</h5>
              <p>You could request for a Special booking, Dinner Reservation, Conference meeting</p>
              <p class="icon"><span class="me-2">
                <i class="fa-solid fa-phone address-icon"></i></span>+2349036655765
              </p>
            </div>
            <div class="info-three">
              <h5>Other Information & Inquires</h5>
              <p>We would love to hear from you about how you enjoyed our services</p>
              <p class="icon"><span class="me-2">
                <i class="fa-solid fa-phone address-icon"></i></span>+23490355786988</p>
            </div>
          </div>
          <div class="form">

            <form action="" method="POST">
              <h5 class="mt-3 mb-4 text-bold align-center">Fill the form below and send</h5>
              <div class="mb-3">
                <label for="name" class="form-label">Name</label>
                <input type="text" name="name" class="form-control" id="name" placeholder="enter name here" />
                {/* <p th:if="${#fields.hasErrors('name')}" th:errors="*{name}" class="text-danger"></p> */}
              </div>
              <div class="mb-3">
                <label for="email" class="form-label">Email address</label>
                <input type="email" name="email" class="form-control" id="email" placeholder="enter email here" />
                {/* <p th:if="${#fields.hasErrors('email')}" th:errors="*{email}" class="text-danger"></p> */}
              </div>
              <div class="mb-3">
                <label for="subject" class="form-label">Subject</label>
                <input type="text" name="subject" class="form-control" id="subject" placeholder="enter subject here"
                />
                {/* <p th:if="${#fields.hasErrors('subject')}" th:errors="*{subject}" class="text-danger"></p> */}
              </div>
              <div class="mb-3">
                <label for="comment" class="form-label">Comment</label>
                <textarea class="form-control" id="comment" name="comment" rows="3"></textarea>
                {/* <p th:if="${#fields.hasErrors('comment')}" th:errors="*{comment}" class="text-danger"></p> */}
              </div>
              <div class="col-auto">
                <button type="submit" class="btn btn-primary mb-3">Send Message</button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </Wrapper>
  )
}

export default ContactInfo;
